DROP TABLE IF EXISTS `premios_sorteos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `premios_sorteos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tipoApuesta` varchar(20) NOT NULL,
  `sorteo` varchar(30) NOT NULL,
  `fecha` date NOT NULL,
  `categoria` varchar(50) NOT NULL,
  `aciertos` varchar(30) NOT NULL,
  `premio` decimal(12,2) NOT NULL,
  `premio_text` varchar(32) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `u1` (`tipoApuesta`,`sorteo`,`fecha`,`categoria`)
) ENGINE=InnoDB AUTO_INCREMENT=7632 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
