DROP TABLE IF EXISTS `primitiva`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `primitiva` (
  `identificador` varchar(40) NOT NULL,
  `sorteoCodigo` varchar(20) DEFAULT NULL,
  `fechaLunes` date DEFAULT NULL,
  `combinacion` varchar(60) DEFAULT NULL,
  `reintegro` varchar(5) DEFAULT NULL,
  `semanas` int(11) DEFAULT NULL,
  `terminal` varchar(20) DEFAULT NULL,
  `joker` varchar(20) DEFAULT NULL,
  `imagen` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`identificador`),
  KEY `fechaLunes` (`fechaLunes`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
