DROP TABLE IF EXISTS `r_euromillones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `r_euromillones` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `semana` int(11) NOT NULL,
  `sorteo` varchar(3) NOT NULL,
  `fecha` date NOT NULL,
  `numeros` varchar(32) NOT NULL,
  `estrellas` varchar(8) NOT NULL,
  `elMillon` varchar(16) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `u1` (`sorteo`,`fecha`)
) ENGINE=InnoDB AUTO_INCREMENT=154 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

